// ============================================
// Guard: ตัดส่วนที่ AI เขียนแทนผู้เล่นทิ้ง
// ============================================

// คำที่ใช้เรียกผู้เล่น
// สำคัญ: ห้ามใส่ "เธอ" เพราะบทบรรยายใช้ "เธอ" แทนแคร์โรไลน์เอง
const PLAYER = '(?:คุณ|ท่าน|ผู้มาเยือน|เจ้าหนู|นักเดินทาง|ชายแปลกหน้า|หญิงแปลกหน้า)';

// กริยาแสดงการกระทำ ความรู้สึก และความคิด
const VERB = '(?:ทำ|พูด|บอก|ตอบ|ถาม|เดิน|ก้าว|นั่ง|ลุก|ยืน|หัน|มอง|จ้อง|ยิ้ม|หัวเราะ|พยักหน้า|ส่ายหน้า|หยิบ|วาง|ยื่น|ดึง|ผลัก|เอื้อม|ก้ม|เงย|รู้สึก|คิด|ตัดสินใจ|นึก|ตกใจ|กลัว|โกรธ|ดีใจ|เสียใจ|ลังเล|สัมผัส|ได้ยิน|เห็น|จำ|รู้|เข้าใจ)';

const PLAYER_ACTION = new RegExp(PLAYER + '\\s*' + VERB);

function stripPlayerNarration(text) {
  // แยกข้อความสลับกันระหว่าง [บทบรรยาย] และ ["บทพูด"]
  const parts = text.split(/(["“][^"”]*["”])/);
  let out = '';
  let cut = false;

  for (const part of parts) {
    const isDialogue = /^["“]/.test(part);

    // ตรวจเฉพาะบทบรรยาย ไม่แตะบทพูดของตัวละคร
    if (!isDialogue) {
      const m = part.match(PLAYER_ACTION);
      if (m) {
        out += part.slice(0, m.index);
        cut = true;
        break;
      }
    }
    out += part;
  }

  out = out.replace(/["“”\s]+$/, '').trim();
  return { text: out, cut };
}

return $input.all().map(item => {
  const original = item.json.output ?? '';
  const { text, cut } = stripPlayerNarration(original);
  const emptied = cut && text.length === 0;

  return {
    json: {
      output: emptied ? original : text,
      guard_triggered: cut,      // ใช้นับตอนวัดผล
      guard_emptied: emptied,    // ตัดจนไม่เหลืออะไร = ถือว่าพลาด
      original_output: original, // เก็บของเดิมไว้เทียบ
    },
  };
});

